<?php
require_once __DIR__.'/_bootstrap.php'; requireMethod('GET'); $u=requireUser(); try { $s=db()->prepare('SELECT profile_json,best_json,updated_at FROM public.player_saves WHERE user_id=:id LIMIT 1'); $s->execute(['id'=>$u['id']]); $r=$s->fetch(); if (!$r) jsonResponse(200,['ok'=>true,'save'=>null]); $profile=is_array($r['profile_json'])?$r['profile_json']:json_decode((string)$r['profile_json'],true); $best=is_array($r['best_json'])?$r['best_json']:json_decode((string)$r['best_json'],true); jsonResponse(200,['ok'=>true,'save'=>['profile'=>is_array($profile)?$profile:(object)[],'best'=>is_array($best)?$best:(object)[],'updatedAt'=>$r['updated_at']]]); } catch(Throwable $e) { error_log('[Bastion load] '.$e->getMessage()); jsonResponse(500,['ok'=>false,'error'=>'Could not load the cloud save.']); }
